properties.query:
[format('let mfaPasswordWindow = {0}m;
let tokenReplayWindow = {1}m;
let lookback = {2}h;
let ExcludedUPNs = dynamic([{3}]);
let MFAResetOperations = dynamic(["User registered security info", "User deleted security info", "User changed default security info method", "Admin registered security info", "Admin deleted security info", "Admin updated security info"]);
let PasswordResetOperations = dynamic(["Reset password (by admin)", "Reset user password", "Change user password", "Change password", "Reset password"]);
let MFAMethodChanges = AuditLogs
| where TimeGenerated > ago(lookback)
| where OperationName has_any (MFAResetOperations)
| extend TargetUPN = tostring(TargetResources[0].userPrincipalName)
| where TargetUPN !in (ExcludedUPNs)
| where not(TargetUPN startswith "svc-")
| project MFAChangeTime = TimeGenerated, TargetUPN, MFAOperation = OperationName, MFAInitiatedBy = tostring(InitiatedBy.user.userPrincipalName), MFAChangeIP = tostring(InitiatedBy.user.ipAddress);
let PasswordResets = AuditLogs
| where TimeGenerated > ago(lookback)
| where OperationName has_any (PasswordResetOperations)
| extend TargetUPN = tostring(TargetResources[0].userPrincipalName)
| where TargetUPN !in (ExcludedUPNs)
| where not(TargetUPN startswith "svc-")
| project PasswordResetTime = TimeGenerated, TargetUPN, PasswordOperation = OperationName, PasswordInitiatedBy = tostring(InitiatedBy.user.userPrincipalName), PasswordResetIP = tostring(InitiatedBy.user.ipAddress);
let DetectionA = MFAMethodChanges
| join kind=inner (PasswordResets) on TargetUPN
| where abs(datetime_diff(''minute'', PasswordResetTime, MFAChangeTime)) <= {4}
| extend TimeBetweenEvents = iff(PasswordResetTime > MFAChangeTime, PasswordResetTime - MFAChangeTime, MFAChangeTime - PasswordResetTime), DetectionType = "MFA_Reset_Plus_Password_Reset"
| project TimeGenerated = MFAChangeTime, DetectionType, UserPrincipalName = TargetUPN, MFAChangeTime, MFAOperation, MFAInitiatedBy, PasswordResetTime, PasswordOperation, PasswordInitiatedBy, TimeBetweenEvents, AccountName = TargetUPN, IPAddress = coalesce(MFAChangeIP, PasswordResetIP);
let MultiIPSignins = SigninLogs
| where TimeGenerated > ago(lookback)
| where ResultType == 0
| where UserPrincipalName !in (ExcludedUPNs)
| where not(UserPrincipalName startswith "svc-")
| summarize DistinctIPs = make_set(IPAddress, 20), IPCount = dcount(IPAddress), FirstSignin = min(TimeGenerated), LastSignin = max(TimeGenerated), Apps = make_set(AppDisplayName, 10) by UserPrincipalName, bin(TimeGenerated, {5}m)
| where IPCount >= {6}
| where (LastSignin - FirstSignin) <= {7}m;
let DetectionB = MultiIPSignins
| extend DetectionType = "Token_Replay_Multi_IP", TimeBetweenEvents = LastSignin - FirstSignin
| project TimeGenerated = FirstSignin, DetectionType, UserPrincipalName, IPCount, DistinctIPs, TimeBetweenEvents, Apps, AccountName = UserPrincipalName, IPAddress = tostring(DistinctIPs[0]);
union DetectionA, DetectionB
| project TimeGenerated, DetectionType, UserPrincipalName, MFAOperation, PasswordOperation, TimeBetweenEvents, IPCount, DistinctIPs, AccountName, IPAddress
| order by TimeGenerated desc', parameters('mfaPasswordWindowMinutes'), parameters('tokenReplayWindowMinutes'), parameters('lookbackPeriodHours'), parameters('excludedUsers'), parameters('mfaPasswordWindowMinutes'), parameters('tokenReplayWindowMinutes'), parameters('multiIpThreshold'), parameters('tokenReplayWindowMinutes'))]
